def check_winner(binary_string):
    # Initialize the state of the game
    state = [int(bit) for bit in binary_string]

    # Function to evaluate the current state
    def evaluate():
        i = 0
        while i < len(state):
            if state[i] == 1:
                return True
            elif state[i] == 0:
                i += 1
            else:
                break
        return False

    # Perform the operations until we have only one operation left
    while len(state) > 1:
        if state[0] == 1:
            state[0] = state[1]
            state.pop(1)
        elif state[-1] == 1:
            state[-1] = state[-2]
            state.pop(-2)
        else:
            if state.count(1) % 2 == 0:
                state[0] = state[1]
                state.pop(1)
            else:
                state[-1] = state[-2]
                state.pop(-2)

    # Check the result of the final state
    return "YES" if evaluate() else "NO"

