def is_alice_wins(binary_string):
    # Check if the initial string has more than one true
    if binary_string.count('1') > 1:
        return False

    # Count the number of '1's before and after the first '1'
    count_before = binary_string[:binary_string.index('1')].count('1')
    count_after = binary_string[binary_string.index('1')+1:].count('1')

    # Determine if Alice can win
    if count_before % 2 == 0 and count_after % 2 != 0:
        return True
    elif count_before % 2 != 0 and count_after % 2 == 0:
        return False
    else:
        return None

