def shape_perimeter(n, m, x, y):
    # Initialize the grid to store the color of each cell
    grid = [[0] * m for _ in range(m)]

    # Initialize the perimeter count
    perimeter = 0

    # Iterate through each operation
    for i in range(n):
        # Update the grid based on the operation
        for j in range(min(x[i], m - 1)):
            grid[x[i] - j][y[i]] = 1
        for j in range(min(y[i], m - 1)):
            grid[x[i]][y[i] - j] = 1
        for j in range(min(m - 1 - x[i], m - 1)):
            grid[x[i] + j][y[i]] = 1
        for j in range(min(m - 1 - y[i], m - 1)):
            grid[x[i]][y[i] + j] = 1

        # Calculate the perimeter
        for i in range(m):
            for j in range(m):
                if grid[i][j] == 1:
                    if i == 0 or grid[i - 1][j] == 0:
                        perimeter += 1
                    if j == 0 or grid[i][j - 1] == 0:
                        perimeter += 1
                    if i == m - 1 or grid[i + 1][j] == 0:
                        perimeter += 1
                    if j == m - 1 or grid[i][j + 1] == 0:
                        perimeter += 1

    return perimeter

