def shape_perimeter(n, m, x, y):
    visited = [[False] * m for _ in range(m)]
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]

    def dfs(i, j):
        if i < 0 or i >= m or j < 0 or j >= m or visited[i][j]:
            return 0
        visited[i][j] = True
        count = 1
        for dx, dy in directions:
            count += dfs(i + dx, j + dy)
        return count

    perimeter = 0
    for i in range(1, n + 1):
        x_val = x[i - 1]
        y_val = y[i - 1]
        for dx, dy in directions:
            nx, ny = i + dx, i + dy
            while 0 <= nx < m and 0 <= ny < m and visited[nx][ny]:
                nx += dx
                ny += dy
            if 0 <= nx < m and 0 <= ny < m and not visited[nx][ny]:
                perimeter += dfs(nx, ny) + 1

    return perimeter

