import math

def find_perpendicular_segments(X, Y, K):
    # Iterate through possible positions for point A
    for A_x in range(X + 1):
        for A_y in range(Y + 1):
            # Check if the distance from A to origin is at least K
            if math.sqrt(A_x**2 + A_y**2) >= K:
                # Iterate through possible positions for point B
                for B_x in range(X + 1):
                    for B_y in range(Y + 1):
                        # Calculate the distance between A and B
                        AB_length = math.sqrt((B_x - A_x)**2 + (B_y - A_y)**2)
                        # Check if AB_length is at least K
                        if AB_length >= K:
                            # Check if points A and B are distinct
                            if (A_x, A_y) != (B_x, B_y):
                                # Iterate through possible positions for point C
                                for C_x in range(X + 1):
                                    for C_y in range(Y + 1):
                                        # Check if the distance from C to origin is at least K
                                        if math.sqrt(C_x**2 + C_y**2) >= K:
                                            # Iterate through possible positions for point D
                                            for D_x in range(X + 1):
                                                for D_y in range(Y + 1):
                                                    # Calculate the distance between C and D
                                                    CD_length = math.sqrt((D_x - C_x)**2 + (D_y - C_y)**2)
                                                    # Check if CD_length is at least K
                                                    if CD_length >= K:
