    for Ax in range(1, X + 1):
        for Ay in range(1, Y + 1):
            # Calculate the slope of AB
            m_AB = (Ay - 0) / (Ax - 0)
            # Check if there exists a point C and D such that CD is perpendicular to AB
            for Cx in range(Ax + 1, X + 1):
                for Cy in range(Y + 1, Y + 1):
                    # Calculate the slope of CD
                    m_CD = (Cy - Ay) / (Cx - Ax)
                    # Check if the product of the slopes is -1 (perpendicular)
                    if abs(m_AB * m_CD) == 1:
                        # Calculate the coordinates of D
                        Dx = int(Cx - (Cy - Ay) / m_CD)
                        Dy = int(Cy + (Cx - Ax) / m_CD)
                        # Check if the lengths of AB and CD are at least K
                        if math.sqrt((Ax - Bx)**2 + (Ay - By)**2) >= K and math.sqrt((Cx - Dx)**2 + (Cy - Dy)**2) >= K:
                            return [Ax, Ay, Bx, By], [Cx, Cy, Dx, Dy]
    return None

