def max_happy_people(n, r, a):
    # Initialize the count of happy people
    happy_count = 0

    # Sort the array in descending order based on the number of family members
    a.sort(reverse=True)

    # Iterate through the sorted array
    for i in range(n):
        # If the current family has only one member, they cannot be happy
        if a[i] == 1:
            continue

        # Try to place the family in the first row
        if i == 0:
            if a[i] < r * 2:
                happy_count += 1
                continue
            else:
                break

        # Try to place the family in the last row
        if i == n - 1:
            if a[i] < r * 2:
                happy_count += 1
                continue
            else:
                break

        # Try to place the family in the middle rows
        if a[i] < r * 2:
            happy_count += 1
            continue
        else:
            break

    return happy_count

