def max_difference(n, a, b):
    # Calculate the total number of problems solved by Monocarp and Stereocarp
    m = sum(a)
    s = sum(b)

    # Determine the optimal strategy for Monocarp and Stereocarp
    # If Monocarp trains on the last day, Stereocarp will not train
    if n == 1:
        return abs(m - s)

    # If Monocarp trains on the first day, Stereocarp will train on the second day
    elif n == 2:
        return abs(m + b[1] - s - a[1])

    # Otherwise, find the optimal strategy
    else:
        # Find the maximum difference between the number of problems solved by Monocarp and Stereocarp
        max_diff = max(abs(m - s), abs(m - s + b[n-1] - a[n-1]))

        # Check if there is another strategy that gives a higher difference
        for i in range(1, n-1):
            diff = abs(m - s + b[i] - a[i])
            if diff > max_diff:
                max_diff = diff

        return max_diff

