    total_sum = sum(a)
    if total_sum % k == 0:
        return False

    # Find the index where the sum of the prefix array is divisible by k
    prefix_sum = [0] * (n + 1)
    for i in range(1, n + 1):
        prefix_sum[i] = prefix_sum[i - 1] + a[i - 1]

    for i in range(1, n):
        if (prefix_sum[i] + k) % k == 0:
            return True

    return False

