def min_timar_operations(n, m, k, s):
    count = 0
    i = 0
    while i < n:
        j = i
        while j < n and j - i + 1 <= m and s[j] == '0':
            j += 1
        if j - i + 1 > m:
            count += 1
        i = j
    return count

