import math

def binomial_coefficient(n, k):
    # Using Pascal's Triangle formula
    if k > n - k:
        k = n - k
    result = 1
    for i in range(k):
        result *= (n - i)
        result //= (i + 1)
    return result % (10**9 + 7)

