def max_coins(n):
    if n <= 3:
        return 1

    # If n is even, we can transform it into two coins with value floor(n/4)
    if n % 2 == 0:
        return 2 + max_coins(n // 4)

    # Otherwise, we need to find the smallest divisor of n greater than 3
    for i in range(4, int(n**0.5) + 1):
        if n % i == 0:
            return 1 + max_coins(i) + max_coins(n // i)

    # If no divisors were found, n itself must be prime and we can only have one coin
    return 1

