def max_coins(n):
    if n <= 3:
        return n
    else:
        # Find the largest power of 4 less than or equal to n
        largest_power_of_4 = 1
        while largest_power_of_4 * 4 <= n:
            largest_power_of_4 *= 4
        # The remaining value after using the largest power of 4
        remaining_value = n - largest_power_of_4
        # The maximum number of coins is the sum of the largest power of 4 and the remaining value divided by 4
        return largest_power_of_4 + remaining_value // 4

