def max_coins(n):
    # Base case: if n is less than or equal to 3, return n
    if n <= 3:
        return n

    # If n is divisible by 4, return n // 4 + 1
    if n % 4 == 0:
        return n // 4 + 1

    # Otherwise, return n // 4 + 1 plus the remainder divided by 4
    return n // 4 + 1 + (n % 4 - 1) // 3

