    visited = set()
    def dfs(i, j):
        if i < 0 or i >= 101 or j < 0 or j >= 101 or grid[i][j] == 0 or (i, j) in visited:
            return
        visited.add((i, j))
        dfs(i+1, j)
        dfs(i-1, j)
        dfs(i, j+1)
        dfs(i, j-1)

    count = 0
    for i in range(101):
        for j in range(101):
            if grid[i][j] == 1 and (i, j) not in visited:
                dfs(i, j)
                count += 1

    # Calculate the perimeter of each connected component
    perimeter = 0
    for i in range(101):
        for j in range(101):
            if grid[i][j] == 1 and (i, j) not in visited:
                visited.add((i, j))
                perimeter += 4
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nx, ny = i + dx, j + dy
                    if 0 <= nx < 101 and 0 <= ny < 101 and grid[nx][ny] == 1:
                        perimeter -= 2

    return perimeter

